using FluNET.Compilation;using FluNET.Prompt;using FluNET.Prompt.Surface;namespace FluNET.Automation;public sealed class AutomationCompiler(SurfaceCompiler surfaceCompiler)
{
 public AutomationCompilationResult Compile(SourceDocument document){List<AutomationDefinition>a=[];List<AutomationDiagnostic>d=[];Line[]lines=ReadLines(document.Text).Where(l=>!string.IsNullOrWhiteSpace(l.Text)&&!l.Text.TrimStart().StartsWith('#')).ToArray();if(lines.Length==0)return new([],[]);int root=lines.Min(l=>l.Indent),cursor=0,index=0;while(cursor<lines.Length){Line header=lines[cursor];if(header.Indent!=root){d.Add(new("FLN310","Automation trigger must start at root indentation.",header.Span));cursor++;continue;}string source=header.Text.Trim();cursor++;List<Line>children=[];while(cursor<lines.Length&&lines[cursor].Indent>root)children.Add(lines[cursor++]);if(children.Count==0){d.Add(new("FLN311","Automation trigger requires an indented workflow body.",header.Span));continue;}TriggerDefinition?trigger=null;IReadOnlyList<Line>body=children;if(source.StartsWith("EVERY ",StringComparison.OrdinalIgnoreCase)){string specification=source[6..].Trim();if(TryCalendar(specification,out TriggerDefinition?calendar,out string?error))trigger=calendar;else if(TryDuration(specification,out TimeSpan interval))trigger=new IntervalTriggerDefinition(interval);else d.Add(new("FLN312",error??$"Invalid EVERY schedule '{specification}'.",header.Span));}else if(source.StartsWith("CRON ",StringComparison.OrdinalIgnoreCase)){if(TryCron(source[5..].Trim(),out CronTriggerDefinition?cron,out string?error))trigger=cron;else d.Add(new("FLN317",error??"Invalid CRON schedule.",header.Span));}else if(source.StartsWith("WATCH ",StringComparison.OrdinalIgnoreCase)){string resource=source[6..].Trim();if(resource.Length==0)d.Add(new("FLN313","WATCH requires a resource expression.",header.Span));else{string?eventName=null;Line first=children[0];if(first.Text.TrimStart().StartsWith("WHEN ",StringComparison.OrdinalIgnoreCase)){eventName=first.Text.Trim()[5..].Trim();int whenIndent=first.Indent;Line[]eventBody=children.Skip(1).Where(l=>l.Indent>whenIndent).ToArray();if(eventName.Length==0||eventBody.Length==0)d.Add(new("FLN314","WHEN requires an event name and body.",first.Span));else body=eventBody;}trigger=new WatchTriggerDefinition(resource,eventName);}}else d.Add(new("FLN315","Expected EVERY, CRON or WATCH automation trigger.",header.Span));if(trigger is null)continue;string bodySource=Deindent(body);SurfaceCompilationResult compilation=surfaceCompiler.Compile(new SourceDocument(bodySource,SourceSyntaxKind.Compact));if(!compilation.IsValid)d.Add(new("FLN316","Automation workflow body does not compile.",header.Span));a.Add(new(AutomationId.Create(source,index++),trigger,new WorkflowTemplate(compilation),header.Span));}return new(a,d);}
 private static bool TryCalendar(string source,out TriggerDefinition?trigger,out string?error){trigger=null;error=null;(string schedule,string zone)=SplitZone(source);if(schedule.StartsWith("DAY AT ",StringComparison.OrdinalIgnoreCase)){if(!TimeOnly.TryParse(schedule[7..].Trim(),System.Globalization.CultureInfo.InvariantCulture,out TimeOnly time)){error="EVERY DAY AT requires a time such as 08:00.";return false;}try{_ = AutomationScheduleCalculator.ResolveZone(zone);}catch(FormatException e){error=e.Message;return false;}trigger=new DailyTimeTriggerDefinition(time,zone);return true;}int at=schedule.IndexOf(" AT ",StringComparison.OrdinalIgnoreCase);if(at>0&&Enum.TryParse(schedule[..at].Trim(),true,out DayOfWeek day)&&TimeOnly.TryParse(schedule[(at+4)..].Trim(),System.Globalization.CultureInfo.InvariantCulture,out TimeOnly weekly)){try{_ = AutomationScheduleCalculator.ResolveZone(zone);}catch(FormatException e){error=e.Message;return false;}trigger=new WeeklyTimeTriggerDefinition(day,weekly,zone);return true;}return false;}
 private static bool TryCron(string source,out CronTriggerDefinition?trigger,out string?error){trigger=null;error=null;string expression,tail;if(source.Length>=2&&source[0] is'"'or'\''){char quote=source[0];int close=source.IndexOf(quote,1);if(close<0){error="CRON expression quote is not closed.";return false;}expression=source[1..close];tail=source[(close+1)..].Trim();}else{int marker=source.LastIndexOf(" IN ",StringComparison.OrdinalIgnoreCase);expression=marker>0?source[..marker].Trim():source;tail=marker>0?source[marker..].Trim():string.Empty;}string zone="UTC";if(tail.Length>0){if(!tail.StartsWith("IN ",StringComparison.OrdinalIgnoreCase)){error="CRON suffix must be `IN timezone`.";return false;}zone=tail[3..].Trim();}try{CronSchedule schedule=CronSchedule.Parse(expression);_ = AutomationScheduleCalculator.ResolveZone(zone);trigger=new(schedule,zone);return true;}catch(Exception e)when(e is FormatException or ArgumentException){error=e.Message;return false;}}
 private static (string Schedule,string Zone)SplitZone(string source){int marker=source.LastIndexOf(" IN ",StringComparison.OrdinalIgnoreCase);return marker>0?(source[..marker].Trim(),source[(marker+4)..].Trim()):(source.Trim(),"UTC");}
 private static string Deindent(IReadOnlyList<Line>lines){int indent=lines.Min(l=>l.Indent);return string.Join(Environment.NewLine,lines.Select(l=>RemoveIndent(l.Text,indent)));}private static string RemoveIndent(string text,int width){int chars=0,consumed=0;while(chars<text.Length&&consumed<width&&text[chars] is' 'or'\t'){consumed+=text[chars]=='\t'?4:1;chars++;}return text[chars..];}
 private static bool TryDuration(string source,out TimeSpan interval){string t=source.Trim().ToLowerInvariant();(string Number,double Seconds)p=t switch{_ when t.EndsWith("ms")=>(t[..^2],.001),_ when t.EndsWith('s')=>(t[..^1],1),_ when t.EndsWith('m')=>(t[..^1],60),_ when t.EndsWith('h')=>(t[..^1],3600),_ when t.EndsWith('d')=>(t[..^1],86400),_=>(string.Empty,0)};if(p.Number.Length==0||!double.TryParse(p.Number,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double n)||n<=0){interval=default;return false;}interval=TimeSpan.FromSeconds(n*p.Seconds);return interval>TimeSpan.Zero&&interval<=TimeSpan.FromDays(365);}
 private static IEnumerable<Line>ReadLines(string source){int start=0;for(int index=0;index<=source.Length;index++){if(index<source.Length&&source[index]!='\n')continue;int length=index-start;if(length>0&&source[start+length-1]=='\r')length--;string text=source.Substring(start,length);int chars=0,indent=0;while(chars<text.Length&&text[chars] is' 'or'\t'){indent+=text[chars]=='\t'?4:1;chars++;}yield return new(text,start,indent,new SourceSpan(start,Math.Max(1,length)));start=index+1;}}private sealed record Line(string Text,int Start,int Indent,SourceSpan Span);
}
